import{_ as s,c as e,o as a,ag as n}from"./chunks/framework.ymCRTBvy.js";const p=JSON.parse('{"title":"10.3_设置keyTimes控制每帧节奏","description":"","frontmatter":{},"headers":[],"relativePath":"swift/uikit/uikit_animation/10.3_设置keyTimes控制每帧节奏.md","filePath":"swift/uikit/uikit_animation/10.3_设置keyTimes控制每帧节奏.md"}'),t={name:"swift/uikit/uikit_animation/10.3_设置keyTimes控制每帧节奏.md"};function o(l,i,d,k,h,r){return a(),e("div",null,i[0]||(i[0]=[n('<h1 id="_10-3-设置keytimes控制每帧节奏" tabindex="-1">10.3_设置keyTimes控制每帧节奏 <a class="header-anchor" href="#_10-3-设置keytimes控制每帧节奏" aria-label="Permalink to &quot;10.3_设置keyTimes控制每帧节奏&quot;">​</a></h1><p>关键帧动画中，<code>keyTimes</code> 属性允许你精确控制动画每一帧的播放节奏。通过设置 <code>keyTimes</code>，你可以让动画在某些关键帧之间快速播放，而在另一些关键帧之间缓慢播放，从而实现更复杂、更生动的动画效果。🎉</p><h2 id="理解-keytimes-属性" tabindex="-1">理解 <code>keyTimes</code> 属性 <a class="header-anchor" href="#理解-keytimes-属性" aria-label="Permalink to &quot;理解 `keyTimes` 属性&quot;">​</a></h2><p><code>keyTimes</code> 是一个 <code>NSNumber</code> 对象的数组，每个 <code>NSNumber</code> 对象代表一个关键帧的时间点，取值范围是 0.0 到 1.0。数组中的元素必须按升序排列。<code>keyTimes</code> 的数量应该与 <code>values</code> 或 <code>path</code> 属性中定义的关键帧数量相同。</p><ul><li><strong>时间点</strong>: 每个 <code>keyTime</code> 值表示动画总时长的一个百分比。例如，<code>0.0</code> 表示动画的开始，<code>1.0</code> 表示动画的结束，<code>0.5</code> 表示动画的中间点。</li><li><strong>节奏控制</strong>: 通过调整 <code>keyTimes</code> 的值，你可以控制动画在不同关键帧之间的速度。如果两个相邻的 <code>keyTime</code> 值之间的差值较小，动画在该段时间内播放速度较快；反之，如果差值较大，动画播放速度较慢。</li></ul><h2 id="如何使用-keytimes" tabindex="-1">如何使用 <code>keyTimes</code> <a class="header-anchor" href="#如何使用-keytimes" aria-label="Permalink to &quot;如何使用 `keyTimes`&quot;">​</a></h2><ol><li><strong>创建 <code>CAKeyframeAnimation</code> 实例</strong>: 首先，你需要创建一个 <code>CAKeyframeAnimation</code> 实例，并设置其 <code>keyPath</code> 属性，指定要动画的属性。</li><li><strong>设置 <code>values</code> 或 <code>path</code> 属性</strong>: 接下来，你需要设置 <code>values</code> 属性（用于属性动画）或 <code>path</code> 属性（用于路径动画），定义动画的关键帧。</li><li><strong>设置 <code>keyTimes</code> 属性</strong>: 创建一个 <code>NSNumber</code> 对象的数组，并将其赋值给 <code>keyTimes</code> 属性。确保 <code>keyTimes</code> 的数量与 <code>values</code> 或 <code>path</code> 中定义的关键帧数量相同。</li><li><strong>添加到图层</strong>: 最后，将动画添加到图层上，动画就会按照你设置的节奏播放。</li></ol><h2 id="示例-自定义动画节奏" tabindex="-1">示例：自定义动画节奏 <a class="header-anchor" href="#示例-自定义动画节奏" aria-label="Permalink to &quot;示例：自定义动画节奏&quot;">​</a></h2><p>假设你想要创建一个颜色变化的动画，从红色变为绿色，再变为蓝色。你希望动画在红色到绿色之间快速变化，而在绿色到蓝色之间缓慢变化。你可以这样设置 <code>keyTimes</code>：</p><div class="language-swift vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">swift</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> animation </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> CAKeyframeAnimation</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">keyPath</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;backgroundColor&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">animation.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">values</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [UIColor.red.cgColor, UIColor.green.cgColor, UIColor.blue.cgColor]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">animation.keyTimes </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 红色到绿色快速，绿色到蓝色缓慢</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">animation.duration </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2.0</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">layer.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">add</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(animation, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">forKey</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;backgroundColorAnimation&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>在这个例子中，<code>keyTimes</code> 的值为 <code>[0.0, 0.2, 1.0]</code>。这意味着：</p><ul><li>动画在 0% 到 20% 的时间内，颜色从红色变为绿色。</li><li>动画在 20% 到 100% 的时间内，颜色从绿色变为蓝色。</li></ul><p>由于红色到绿色之间的时间间隔较短 (0.2 - 0.0 = 0.2)，因此颜色变化速度较快。而绿色到蓝色之间的时间间隔较长 (1.0 - 0.2 = 0.8)，因此颜色变化速度较慢。</p><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ul><li><code>keyTimes</code> 数组中的元素必须按升序排列，否则动画可能无法正常播放。</li><li><code>keyTimes</code> 的数量必须与 <code>values</code> 或 <code>path</code> 中定义的关键帧数量相同，否则动画的行为将是未定义的。</li><li>如果你没有设置 <code>keyTimes</code> 属性，动画将以匀速播放。</li></ul><p>通过灵活运用 <code>keyTimes</code> 属性，你可以创建出各种各样具有节奏感的动画效果，让你的应用更加生动有趣。🚀 记住，实践是最好的老师，多尝试不同的 <code>keyTimes</code> 值，你就能掌握动画节奏控制的精髓！</p>',16)]))}const m=s(t,[["render",o]]);export{p as __pageData,m as default};
